using System; using System.Collections.Generic; using System.Linq;
namespace Crownfall.Stats { public sealed class StatModifierSet { readonly List<StatModifier> items=new List<StatModifier>(); public IReadOnlyList<StatModifier> Items=>items; public void AddOrReplace(StatModifier m){var i=items.FindIndex(x=>x.Id==m.Id&&x.Source==m.Source);if(i>=0)items[i]=m;else items.Add(m);} public void RemoveSource(string source)=>items.RemoveAll(x=>x.Source==source); public float Calculate(StatType stat,float baseValue){var a=items.Where(x=>x.Stat==stat).OrderBy(x=>x.Priority).ToList();float flat=0,add=0,mul=1;float? ov=null;foreach(var x in a){switch(x.Operation){case ModifierOperation.Flat:flat+=x.Value;break;case ModifierOperation.AdditivePercent:add+=x.Value;break;case ModifierOperation.MultiplicativePercent:mul*=1+x.Value;break;case ModifierOperation.Override:ov=x.Value;break;}}float v=(baseValue+flat)*(1+add)*mul;if(ov.HasValue)v=ov.Value;return Clamp(stat,v);} static float Clamp(StatType s,float v){switch(s){case StatType.AttackSpeed:return Math.Min(3.5f,Math.Max(0.05f,v));case StatType.CritChance:return Math.Min(1f,Math.Max(0,v));case StatType.CritDamage:return Math.Min(3f,Math.Max(1f,v));case StatType.Dodge:return Math.Min(.5f,Math.Max(0,v));case StatType.Tenacity:return Math.Min(.7f,Math.Max(0,v));default:return v;}} } }
